import numpy as np

def make_obs(agent_cells, reward_cells, moving_cells, obstacle_cells, prev_cells):
    x = np.zeros((10,10,5), dtype=float)
    for r,c in agent_cells:
        x[r,c,0] = 1
    for r,c in moving_cells:
        x[r,c,1] = 1
    for r,c in reward_cells:
        x[r,c,2] = 1
    for r,c in obstacle_cells:
        x[r,c,3] = 1
    for r,c in prev_cells:
        x[r,c,4] = 1
    for r in range(10):
        for c in range(10):
            if r==0 or r==9 or c==0 or c==9:
                x[r,c,3] = 1
    return x.flatten()

dirs = {
    'up':    (1, -1, 0),
    'down':  (2,  1, 0),
    'left':  (3,  0,-1),
    'right': (4,  0, 1)
}

states = []
meta = []

for dname, (action, dr, dc) in dirs.items():
    if dname in ['right', 'left']:
        rows = [2,4,6]
        if dname == 'right':
            cols = [2,4]
        else:
            cols = [4,6]
        for r in rows:
            for c in cols:
                if dname == 'right':
                    agent = [(r,c), (r,c+1), (r,c+2)]
                    prev  = [(r,c-1), (r,c), (r,c+1)]
                    reward = [(r,c+3)]
                else:
                    agent = [(r,c-2), (r,c-1), (r,c)]
                    prev  = [(r,c-1), (r,c), (r,c+1)]
                    reward = [(r,c-3)]
                states.append(make_obs(agent, reward, [], [], prev))
                meta.append((dname, action, 'with_prev'))
                states.append(make_obs(agent, reward, [], [], []))
                meta.append((dname, action, 'no_prev'))
    else:
        cols = [2,4,6]
        if dname == 'down':
            rows = [2,4]
        else:
            rows = [4,6]
        for r in rows:
            for c in cols:
                if dname == 'down':
                    agent = [(r,c), (r+1,c), (r+2,c)]
                    prev  = [(r-1,c), (r,c), (r+1,c)]
                    reward = [(r+3,c)]
                else:
                    agent = [(r-2,c), (r-1,c), (r,c)]
                    prev  = [(r-1,c), (r,c), (r+1,c)]
                    reward = [(r-3,c)]
                states.append(make_obs(agent, reward, [], [], prev))
                meta.append((dname, action, 'with_prev'))
                states.append(make_obs(agent, reward, [], [], []))
                meta.append((dname, action, 'no_prev'))

X = np.array(states)
print("Number of states:", len(X))
logits = forward(X)
actions = np.argmax(logits, axis=1)

from collections import defaultdict
counts = defaultdict(lambda: [0,0])
for (dname, target_action, cond), act in zip(meta, actions):
    counts[(dname, cond)][1] += 1
    if act == target_action:
        counts[(dname, cond)][0] += 1

print("Match rates (action == intended direction):")
for dname in dirs:
    for cond in ['with_prev', 'no_prev']:
        match, total = counts[(dname, cond)]
        print(f"{dname:5s} {cond:9s}: {match}/{total} = {match/total:.2f}")

for cond in ['with_prev', 'no_prev']:
    match = sum(counts[(d, cond)][0] for d in dirs)
    total = sum(counts[(d, cond)][1] for d in dirs)
    print(f"Overall {cond}: {match}/{total} = {match/total:.2f}")
